// Normaliza noticias RSS y excluye:
// 1. URLs duplicadas.
// 2. Noticias ya guardadas en Airtable.
// 3. Distintas publicaciones sobre el mismo acontecimiento.

function normalizeUrl(value) {
  if (!value) return '';

  return String(value)
    .trim()
    .split('#')[0]
    .replace(/\/$/, '')
    .toLowerCase();
}

// Palabras frecuentes que no ayudan a identificar el acontecimiento.
const stopWords = new Set([
  'a', 'al', 'ante', 'bajo', 'con', 'contra', 'de', 'del', 'desde',
  'durante', 'e', 'el', 'ella', 'en', 'entre', 'es', 'esta', 'este',
  'estos', 'estas', 'ha', 'hacia', 'hasta', 'la', 'las', 'le', 'lo',
  'los', 'más', 'menos', 'para', 'pero', 'por', 'que', 'se', 'sin',
  'sobre', 'su', 'sus', 'tras', 'un', 'una', 'uno', 'unos', 'unas',
  'y', 'ya', 'como', 'cuándo', 'cuando', 'qué', 'cual', 'cuál'
]);

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9ñ\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Unifica algunas variantes frecuentes para mejorar la comparación.
function canonicalToken(token) {
  const equivalents = {
    compra: 'comprar',
    compro: 'comprar',
    comprara: 'comprar',
    comprará: 'comprar',
    comprando: 'comprar',
    autorizada: 'autorizar',
    autorizado: 'autorizar',
    autoriza: 'autorizar',
    autorizo: 'autorizar',
    autorizó: 'autorizar',
    bancos: 'banco',
    digitales: 'digital',
    argentinos: 'argentina',
    argentinas: 'argentina'
  };

  return equivalents[token] || token;
}

function titleTokens(title) {
  return new Set(
    normalizeText(title)
      .split(' ')
      .map(canonicalToken)
      .filter(token => token.length > 2 && !stopWords.has(token))
  );
}

// Coeficiente Dice:
// 0 = títulos totalmente diferentes.
// 1 = títulos equivalentes.
function titleSimilarity(titleA, titleB) {
  const tokensA = titleTokens(titleA);
  const tokensB = titleTokens(titleB);

  if (!tokensA.size || !tokensB.size) return 0;

  let shared = 0;

  for (const token of tokensA) {
    if (tokensB.has(token)) shared++;
  }

  return (2 * shared) / (tokensA.size + tokensB.size);
}

function isSameStory(titleA, titleB) {
  const tokensA = titleTokens(titleA);
  const tokensB = titleTokens(titleB);

  if (!tokensA.size || !tokensB.size) return false;

  let shared = 0;

  for (const token of tokensA) {
    if (tokensB.has(token)) shared++;
  }

  const similarity = (2 * shared) / (tokensA.size + tokensB.size);
  const containment =
    shared / Math.min(tokensA.size, tokensB.size);

  // Detecta titulares equivalentes sin eliminar noticias distintas
  // que solo comparten términos generales como "banco" o "BCRA".
  return (
  (shared >= 4 && similarity >= 0.40) ||
  (shared >= 5 && containment >= 0.60)
);
}

// Las noticias vienen directamente de "Limitar Noticias".
const newsItems = $('Limitar Noticias').all();

// Historial almacenado en Airtable.
let historyItems = [];

try {
  historyItems = $('Leer Historial Temas').all();
} catch (error) {
  historyItems = [];
}

// Airtable puede entregar las columnas dentro de "fields".
const history = historyItems
  .map(item => item.json.fields || item.json || {})
  .filter(fields => Object.keys(fields).length > 0);

const historicalUrls = new Set(
  history
    .map(fields => normalizeUrl(fields.URL || fields.url || ''))
    .filter(Boolean)
);

const historicalTitles = history
  .map(fields =>
    String(
      fields['Título'] ||
      fields.Titulo ||
      fields.Title ||
      fields.title ||
      ''
    ).trim()
  )
  .filter(Boolean);

// Máximo configurado en "Configurar Ejecucion".
let maxCandidates = 8;

try {
  maxCandidates =
    Number($('Configurar Ejecucion').first().json.max_candidates) || 8;
} catch (error) {
  maxCandidates = 8;
}

const seenUrls = new Set();
const candidates = [];
const duplicatesSkipped = [];

for (const item of newsItems) {
  const data = item.json || {};

  const title = String(data.title || data.Titulo || '').trim();
  const url = String(data.link || data.url || data.URL || '').trim();
  const normalizedUrl = normalizeUrl(url);

  if (!title || !normalizedUrl) continue;
  if (seenUrls.has(normalizedUrl)) continue;
  if (historicalUrls.has(normalizedUrl)) continue;

  // Excluye noticias similares a temas ya guardados.
  const repeatedInHistory = historicalTitles.some(
    historicalTitle => isSameStory(title, historicalTitle)
  );

  if (repeatedInHistory) {
    duplicatesSkipped.push({
      title,
      reason: 'Tema similar ya existente en Airtable'
    });
    continue;
  }

  // Excluye publicaciones de diferentes medios sobre el mismo hecho.
  const repeatedInCandidates = candidates.find(
    candidate => isSameStory(title, candidate.title)
  );

  if (repeatedInCandidates) {
    duplicatesSkipped.push({
      title,
      reason: 'Mismo acontecimiento que otro candidato',
      similar_to: repeatedInCandidates.title,
      similarity: Number(
        titleSimilarity(title, repeatedInCandidates.title).toFixed(2)
      )
    });
    continue;
  }

  seenUrls.add(normalizedUrl);

  candidates.push({
    title,
    summary: String(
      data.contentSnippet ||
      data.summary ||
      data.description ||
      ''
    ).trim(),
    url,
    normalized_url: normalizedUrl,
    published_at:
      data.isoDate ||
      data.pubDate ||
      data.published ||
      '',
    source:
      data.creator ||
      data.author ||
      data.source ||
      'Google News'
  });

  if (candidates.length >= maxCandidates) break;
}

return [
  {
    json: {
      candidates,
      candidates_count: candidates.length,
      historical_titles: historicalTitles,
      duplicates_skipped: duplicatesSkipped,
      duplicates_skipped_count: duplicatesSkipped.length
    }
  }
];

// Parsea la respuesta JSON de OpenAI, valida el Top 3
// y recalcula las puntuaciones de forma segura.

function stripFences(value) {
  return String(value || '')
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
}

function toNum(value) {
  const number = Number(value);

  if (!Number.isFinite(number)) return 0;

  return Math.max(0, Math.min(100, number));
}

function normalizeUrl(value) {
  if (!value) return '';

  return String(value)
    .trim()
    .split('#')[0]
    .replace(/\/$/, '')
    .toLowerCase();
}

function calculateScore(data) {
  const viralidad = toNum(data.viralidad);
  const afinidad = toNum(data.afinidad);
  const utilidad = toNum(data.utilidad);
  const urgencia = toNum(data.urgencia);
  const originalidad = toNum(data.originalidad);

  const score =
    viralidad * 0.35 +
    afinidad * 0.25 +
    utilidad * 0.20 +
    urgencia * 0.10 +
    originalidad * 0.10;

  return {
    viralidad,
    afinidad,
    utilidad,
    urgencia,
    originalidad,
    score_total: Math.round(score * 100) / 100
  };
}

function toText(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value.trim();

  if (Array.isArray(value)) {
    return value
      .map((element, index) => {
        if (typeof element === 'string') return element;

        if (element && typeof element === 'object') {
          const label =
            element.placa ||
            element.escena ||
            element.historia ||
            `Parte ${index + 1}`;

          const text =
            element.texto ||
            element.contenido ||
            element.descripcion ||
            JSON.stringify(element);

          return `${label}: ${text}`;
        }

        return String(element);
      })
      .join('\n');
  }

  return JSON.stringify(value);
}

// Obtiene la respuesta del nodo OpenAI.
const raw =
  $json.output &&
  $json.output[0] &&
  $json.output[0].content &&
  $json.output[0].content[0]
    ? $json.output[0].content[0].text
    : ($json.text !== undefined ? $json.text : $json);

let parsed;

if (raw && typeof raw === 'object') {
  parsed = raw;
} else {
  try {
    parsed = JSON.parse(stripFences(raw));
  } catch (error) {
    throw new Error(
      'No se pudo parsear el JSON de OpenAI: ' +
      (error && error.message ? error.message : String(error))
    );
  }
}

if (!parsed || typeof parsed !== 'object') {
  throw new Error('OpenAI no devolvió un objeto JSON válido.');
}

// Normaliza y valida el Top 3.
const rawTop3 = Array.isArray(parsed.top_3_alternativas)
  ? parsed.top_3_alternativas
  : [];

// Si OpenAI no devuelve el Top 3, el flujo continúa con el tema principal.

const top3 = rawTop3
  .slice(0, 3)
  .map((alternative, index) => {
    const scores = calculateScore(alternative || {});

    return {
      ...(alternative || {}),
      puesto: index + 1,
      ...scores
    };
  })
  .sort((a, b) => b.score_total - a.score_total)
  .map((alternative, index) => ({
    ...alternative,
    puesto: index + 1
  }));

// Recalcula las métricas principales.
const mainScores = calculateScore(parsed);

const result = {
  ...parsed,
  ...mainScores,
  title: String(parsed.title || '').trim(),
  summary: String(parsed.summary || '').trim(),
  url: String(parsed.url || '').trim(),
  source: String(parsed.source || '').trim(),
  published_at: String(parsed.published_at || '').trim(),
  justification: toText(parsed.justification),
  formato: String(parsed.formato || '').trim(),
  gancho: toText(parsed.gancho),
  guion: toText(parsed.guion),
  caption: toText(parsed.caption),
  cta: toText(parsed.cta),
  top_3_alternativas: top3,
  top_3_resumen: top3
    .map(
      alternative =>
        `${alternative.puesto}. ${alternative.title} — Score: ${alternative.score_total}`
    )
    .join('\n'),
  idempotency_key: normalizeUrl(parsed.url),
  decision: String(parsed.decision || '').trim().toLowerCase()
};

return [
  {
    json: result
  }
];

